// Deterministic validation between the AI extraction and the ledger. No AI decides anything here.
const cfg = $('Config').first().json;
const x = $('AI: extract fields from document').first().json.fields || {};
const file = $('Webhook: invoice received (email, drive or upload)').first().json.body.file_name;
const suppliers = $('Accounting: supplier master').first().json.rows;
const pos = $('Accounting: open purchase orders').first().json.rows;
const norm = s => String(s || '').toLowerCase().replace(/\b(llc|fze|fzco|ltd|co|company|est)\b\.?/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
const sd = $getWorkflowStaticData('global'); sd.seen = sd.seen || {};
const reasons = []; let status = 'AUTO_APPROVE';
const key = norm(x.supplier) + '|' + String(x.invoice_no || '').toUpperCase();
if (!x.supplier || !x.invoice_no) { reasons.push('V-00 Extraction incomplete'); status = 'REVIEW'; }
if (sd.seen[key]) { reasons.push('V-01 Duplicate invoice number for this supplier'); status = 'REJECT'; }
const sup = suppliers.find(s => norm(s.supplier_name) === norm(x.supplier));
if (!sup) { reasons.push('V-02 Supplier not in master, new supplier approval required'); if (status !== 'REJECT') status = 'REVIEW'; }
else {
  const trn = String(x.trn || '');
  if (!/^\d{15}$/.test(trn)) { reasons.push(`V-03 TRN format invalid (${trn})`); status = 'REJECT'; }
  else if (trn !== sup.trn) { reasons.push('V-04 TRN differs from supplier master'); status = 'REJECT'; }
}
const sum = (x.line_items || []).reduce((s, l) => s + Number(l.amount || 0), 0);
if (Math.abs(sum - Number(x.subtotal || 0)) > Number(cfg.total_tolerance)) { reasons.push('V-05 Line items do not add to subtotal'); if (status !== 'REJECT') status = 'REVIEW'; }
if (Math.abs(Number(x.subtotal || 0) * 1.05 - Number(x.total || 0)) > Number(cfg.total_tolerance)) { reasons.push('V-06 Total is not subtotal plus 5% VAT'); if (status !== 'REJECT') status = 'REVIEW'; }
if (Number(x.confidence || 0) < 0.9) { reasons.push(`V-07 Extraction confidence ${x.confidence}`); if (status !== 'REJECT') status = 'REVIEW'; }
const po = pos.find(p => norm(p.supplier) === norm(x.supplier) && Math.abs(Number(p.amount) - Number(x.total)) <= 1);
if (!po && Number(x.total || 0) > Number(cfg.auto_approve_limit)) { reasons.push(`V-08 Over auto approve limit (AED ${cfg.auto_approve_limit}) with no matching PO`); if (status !== 'REJECT') status = 'REVIEW'; }
if (sup && Number(x.total || 0) > Number(sup.approved_limit_aed || 0) && !po) { reasons.push(`V-09 Over supplier limit AED ${sup.approved_limit_aed}`); if (status !== 'REJECT') status = 'REVIEW'; }
if (status !== 'REJECT') sd.seen[key] = Date.now();
return [{ json: { file, status, reasons, po_number: po ? po.po_number : null, supplier: x.supplier, trn: x.trn, invoice_no: x.invoice_no, date: x.date, subtotal: x.subtotal, vat: x.vat, total: x.total, currency: x.currency, confidence: x.confidence, line_items: x.line_items } }];

const v = $('Validate: TRN, duplicate, totals, PO match, limit').first().json;
const r = $json;
return [{ json: { file: v.file, status: v.status, reasons: v.reasons, supplier: v.supplier, invoice_no: v.invoice_no, total: v.total, po_number: v.po_number, result: r.bill_id ? { bill_id: r.bill_id } : r.ticket ? { ticket: r.ticket } : { alerted: true } } }];
